CREATE OR REPLACE FUNCTION public.card_power_v2(p_card jsonb, p_blocks jsonb, p_b jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
